    -- providers. If this is set to `true` the client supports the new
    -- `FoldingRangeRegistrationOptions` return value for the corresponding
    -- server capability as well.
    { "dynamicRegistration", "*bool", "dynamicRegistration,omitzero" },
    -- The maximum number of folding ranges that the client prefers to receive
    -- per document. The value serves as a hint, servers are free to follow the
    -- limit.
    { "rangeLimit", "*uint32", "rangeLimit,omitzero" },
    -- If set, the client signals that it only supports folding complete lines.
    -- If set, client will ignore specified `startCharacter` and `endCharacter`
    -- properties in a FoldingRange.
    { "lineFoldingOnly", "*bool", "lineFoldingOnly,omitzero" },
    -- Specific options for the folding range kind.
    --
    -- Since: 3.17.0
    { "foldingRangeKind", "*ClientFoldingRangeKindOptions", "foldingRangeKind,omitzero" },
    -- Specific options for the folding range.
    --
    -- Since: 3.17.0
    { "foldingRange", "*ClientFoldingRangeOptions", "foldingRange,omitzero" },
})

