-- Since: 3.16.0
lsproto.defineStruct("SemanticTokensClientCapabilities", true, {
    -- Whether implementation supports dynamic registration. If this is set to `true`
    -- the client supports the new `(TextDocumentRegistrationOptions & StaticRegistrationOptions)`
    -- return value for the corresponding server capability as well.
    { "dynamicRegistration", "*bool", "dynamicRegistration,omitzero" },
    -- Which requests the client supports and might send to the server
    -- depending on the server's capability. Please note that clients might not
    -- show semantic tokens or degrade some of the user experience if a range
    -- or full request is advertised by the client but not provided by the
    -- server. If for example the client capability `requests.full` and
    -- `request.range` are both set to true but the server only provides a
    -- range provider the client might not render a minimap correctly or might
    -- even decide to not show any semantic tokens at all.
    { "requests", "*ClientSemanticTokensRequestOptions", "requests", "required" },
    -- The token types that the client supports.
    { "tokenTypes", "[]string", "tokenTypes", "required" },
    -- The token modifiers that the client supports.
    { "tokenModifiers", "[]string", "tokenModifiers", "required" },
    -- The token formats the clients supports.
    { "formats", "[]TokenFormat", "formats", "required" },
    -- Whether the client supports tokens that can overlap each other.
    { "overlappingTokenSupport", "*bool", "overlappingTokenSupport,omitzero" },
    -- Whether the client supports tokens that can span multiple lines.
    { "multilineTokenSupport", "*bool", "multilineTokenSupport,omitzero" },
    -- Whether the client allows the server to actively cancel a
    -- semantic token request, e.g. supports returning
    -- LSPErrorCodes.ServerCancelled. If a server does the client
    -- needs to retrigger the request.
    --
    -- Since: 3.17.0
    { "serverCancelSupport", "*bool", "serverCancelSupport,omitzero" },
    -- Whether the client uses semantic tokens to augment existing
    -- syntax tokens. If set to `true` client side created syntax
    -- tokens and semantic tokens are both used for colorization. If
    -- set to `false` the client only uses the returned semantic tokens
    -- for colorization.
    --
    -- If the value is `undefined` then the client behavior is not
    -- specified.
    --
    -- Since: 3.17.0
    { "augmentsSyntaxTokens", "*bool", "augmentsSyntaxTokens,omitzero" },
})

