lsproto.defineEnum("WatchKind", "uint32")
local WatchKind_bits = {
    { 1, "Create" },
    { 2, "Change" },
    { 4, "Delete" },
}

function lsproto.WatchKind_String(e)
    if e == 0 then
        return "0"
    end
    local parts = {}
    for _, b in ipairs(WatchKind_bits) do
        if e & b[1] ~= 0 then
            parts[#parts + 1] = b[2]
        end
    end
    if #parts == 0 then
        return "WatchKind(" .. tostring(e) .. ")"
    end
    return table.concat(parts, "|")
end

